<header class="sticky top-0 z-20 flex h-20 shrink-0 items-center justify-between gap-3 border-b border-slate-200 bg-white px-4 sm:px-8">
    <div class="flex items-center gap-3"><button type="button" @click="sidebarOpen=!sidebarOpen" aria-label="Buka atau tutup menu" class="rounded-xl p-3 text-slate-600 hover:bg-slate-100"><svg class="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true"><path stroke-linecap="round" stroke-width="2" d="M4 6h16M4 12h16M4 18h16"/></svg></button><span class="hidden text-sm font-semibold text-slate-700 sm:block">Operasional <span class="mx-2 text-slate-300">/</span> Shift tim</span></div>
    <div class="flex items-center gap-3"><span class="hidden text-xs text-slate-500 md:block" x-text="activeDirty?'Ada perubahan belum disimpan':'Jadwal tersimpan'"></span><button type="button" @click="saveCurrent()" :disabled="saving||loading||!activeDirty||activeConflicts.length>0||(dateMode&&!calendarReady)" class="min-h-[44px] rounded-xl bg-brand-600 px-4 py-2.5 text-sm font-semibold text-white transition hover:bg-brand-700 disabled:cursor-not-allowed disabled:opacity-40"><span x-text="saving?'Menyimpan…':(dateMode?'Simpan tanggal':'Simpan pola rutin')"></span></button></div>
</header>
<div class="mx-auto w-full max-w-[1600px] space-y-6 p-4 pb-20 sm:p-8">
    <section class="flex flex-col justify-between gap-5 rounded-2xl border border-emerald-100 bg-gradient-to-br from-white to-brand-50 p-6 sm:flex-row sm:items-center sm:p-8">
        <div><p class="mb-2 text-xs font-bold uppercase tracking-[.18em] text-brand-700">Jadwal yang mengikuti timmu</p><h1 class="text-2xl font-extrabold tracking-tight text-slate-900 sm:text-3xl">Atur orangnya. Susun shiftnya.</h1><p class="mt-3 max-w-xl text-sm leading-6 text-slate-600">Ganti sesi dan alat per nama. Pratinjau jadwal serta estimasi produksi langsung mengikuti pengaturanmu.</p></div>
        <div class="flex items-center gap-3 rounded-xl border border-white bg-white/90 px-5 py-4"><span class="flex h-11 w-11 items-center justify-center rounded-full bg-brand-50 text-brand-700"><svg class="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.7" d="M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 012 2v14a2 2 0 01-2 2H5a2 2 0 01-2-2V6a2 2 0 012-2z"/></svg></span><div><p class="text-xs text-slate-500">Zona waktu jadwal</p><p class="mt-1 text-sm font-bold text-slate-900">WITA · UTC+8</p></div></div>
    </section>
    <div role="status" aria-live="polite"><p x-show="loading" class="rounded-xl bg-white p-4 text-sm text-slate-500">Memuat pengaturan tim…</p><p x-show="saved" x-text="saved" class="rounded-xl border border-brand-200 bg-brand-50 p-4 text-sm text-brand-700"></p></div>
    <p x-show="error" x-text="error" role="alert" class="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700"></p>
    <div x-show="!loading" class="space-y-6">
        <section class="grid grid-cols-2 gap-3 xl:grid-cols-4">
            <template x-for="stat in [{label:'Anggota di jadwal',value:summaryConfig.karyawan.length,unit:'orang'},{label:'Sesi terisi',value:assignedSlots,unit:'dari '+(summaryConfig.sessions_count*summaryConfig.tools_count)+' slot'},{label:'Produksi harian',value:number(dailyHours),unit:'jam video'},{label:'Alat tersedia',value:summaryConfig.tools_count,unit:(summaryConfig.tools_count*summaryConfig.hp_per_tool)+' HP'}]" :key="stat.label"><div class="rounded-2xl border border-slate-200 bg-white p-5"><p class="text-xs font-medium text-slate-500" x-text="stat.label"></p><p class="mt-3 text-2xl font-bold tabular-nums text-slate-900" x-text="stat.value"></p><p class="mt-1 text-xs text-slate-500" x-text="stat.unit"></p></div></template>
        </section>
        <nav aria-label="Tampilan pengaturan shift" class="flex gap-1 overflow-x-auto border-b border-slate-200">
            <template x-for="item in [{id:'kalender',name:'Kalender'},{id:'tim',name:'Pola rutin'},{id:'jadwal',name:'Jadwal harian'},{id:'bulanan',name:'Simulasi bulanan'}]" :key="item.id"><button type="button" @click="tab=item.id" :aria-current="tab===item.id?'page':false" :class="tab===item.id?'border-brand-600 text-brand-700':'border-transparent text-slate-500 hover:text-slate-900'" class="min-h-[48px] shrink-0 border-b-2 px-4 py-3 text-sm font-semibold" x-text="item.name"></button></template>
        </nav>
        <section x-show="activeConflicts.length" class="rounded-2xl border border-amber-200 bg-amber-50 p-5" aria-live="polite"><h2 class="text-sm font-bold text-amber-900">Ada jadwal yang perlu dirapikan</h2><p class="mt-1 text-sm text-amber-800">Satu alat hanya bisa digunakan satu orang pada sesi yang sama.</p><ul class="mt-3 list-inside list-disc space-y-1 text-sm text-amber-900"><template x-for="message in activeConflicts" :key="message"><li x-text="message"></li></template></ul></section>
        @include('shifts.calendar')
        <section x-show="tab==='tim'" class="grid items-start gap-6 xl:grid-cols-[minmax(0,1fr)_300px]">
            <div class="overflow-hidden rounded-2xl border border-slate-200 bg-white">
                <div class="space-y-4 border-b border-slate-100 p-5 sm:p-6"><div><h2 class="text-lg font-bold text-slate-900">Pola rutin per anggota</h2><p class="mt-1 text-sm text-slate-500">Pola dasar untuk tanggal yang belum memiliki jadwal khusus. Hari libur tetap mengikuti pengaturan di kanan.</p></div><label class="block"><span class="sr-only">Cari nama anggota</span><input type="search" x-model="search" placeholder="Cari nama anggota…" class="min-h-[44px] w-full rounded-xl border border-slate-200 bg-slate-50 px-4 text-sm outline-none focus:border-brand-500"></label></div>
                <div class="divide-y divide-slate-100">
                    <template x-for="row in visibleWorkers" :key="row.index"><article class="p-5 sm:p-6">
                        <div class="mb-4 flex items-start justify-between gap-3"><div class="flex min-w-0 items-center gap-3"><span class="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-brand-50 text-xs font-bold text-brand-700" x-text="initials(row.person.name)"></span><div class="min-w-0"><h3 class="break-words text-sm font-bold text-slate-900" x-text="row.person.name"></h3><p class="mt-1 text-xs text-slate-500" x-text="row.person.sessions.length?row.person.sessions.length+' sesi · '+number(hours(row.person))+' jam kerja':'Belum dijadwalkan'"></p></div></div><button type="button" @click="removeWorker(row.index)" :aria-label="'Hapus '+row.person.name+' dari jadwal'" class="min-h-[44px] shrink-0 rounded-lg px-3 text-xs text-slate-400 hover:bg-red-50 hover:text-red-700">Hapus</button></div>
                        <div class="grid gap-3 sm:grid-cols-2"><label class="text-xs font-semibold text-slate-600">Nama anggota<select x-model="row.person.name" class="mt-2 min-h-[44px] w-full rounded-lg border border-slate-200 bg-white px-3 text-sm font-normal text-slate-800"><template x-for="name in namesFor(row.person)" :key="name"><option :value="name" x-text="name"></option></template></select></label><label class="text-xs font-semibold text-slate-600">Alat yang digunakan<select x-model="row.person.alat" class="mt-2 min-h-[44px] w-full rounded-lg border border-slate-200 bg-white px-3 text-sm font-normal text-slate-800"><option value="" disabled>Pilih alat</option><template x-for="tool in tools" :key="tool"><option :value="tool" x-text="tool"></option></template></select></label></div>
                        <fieldset class="mt-4"><legend class="mb-2 text-xs font-semibold text-slate-600">Pilih sesi kerja</legend><div class="flex flex-wrap gap-2"><template x-for="session in sessions" :key="session.id"><button type="button" @click="toggleSession(row.person,session.id)" :aria-pressed="row.person.sessions.includes(session.id)" :aria-label="row.person.name+', sesi '+session.id+', '+session.start+' sampai '+session.end" :class="row.person.sessions.includes(session.id)?'border-brand-600 bg-brand-50 text-brand-700':'border-slate-200 bg-white text-slate-500 hover:border-brand-300'" class="min-h-[52px] rounded-lg border px-3 py-2 text-left transition"><span class="block text-xs font-bold" x-text="'Sesi '+session.id"></span><span class="mt-1 block text-[11px] tabular-nums" x-text="session.start+'–'+session.end"></span></button></template></div></fieldset>
                        <p class="mt-3 text-xs text-slate-500">Estimasi produksi: <strong class="font-semibold text-slate-700" x-text="number(production(row.person))+' jam video/hari'"></strong></p>
                    </article></template>
                    <p x-show="visibleWorkers.length===0" class="p-8 text-center text-sm text-slate-500">Tidak ada anggota yang cocok dengan pencarianmu.</p>
                </div>
                <div class="border-t border-slate-100 bg-slate-50 p-5 sm:p-6"><label for="add-worker" class="mb-2 block text-xs font-semibold text-slate-600">Tambahkan anggota dari kontributor</label><div class="flex flex-col gap-2 sm:flex-row"><select id="add-worker" x-model="addName" class="min-h-[44px] min-w-0 flex-1 rounded-lg border border-slate-200 bg-white px-3 text-sm"><option value="">Pilih nama anggota</option><template x-for="person in availablePeople" :key="person.id"><option :value="person.nama" x-text="person.nama"></option></template></select><button type="button" @click="addWorker()" :disabled="!addName" class="min-h-[44px] rounded-lg border border-brand-200 bg-white px-4 text-sm font-semibold text-brand-700 disabled:opacity-40">Tambah anggota</button></div></div>
            </div>
            <aside class="space-y-4"><div class="rounded-2xl border border-slate-200 bg-white p-5"><h2 class="text-base font-bold text-slate-900">Ritme operasional</h2><p class="mt-2 text-xs leading-5 text-slate-500">Waktu sesi berlaku untuk seluruh anggota. Simpan pola rutin untuk menerapkannya ke tanggal tanpa jadwal khusus.</p><div class="mt-5 grid grid-cols-2 gap-4">
                <label class="col-span-2 text-xs font-semibold text-slate-600">Mulai operasional<input type="time" x-model="config.start_time" required class="mt-2 min-h-[44px] w-full rounded-lg border border-slate-200 px-3 text-sm font-normal"></label>
                <label class="text-xs font-semibold text-slate-600">Durasi sesi (menit)<input type="number" min="1" max="1440" x-model.number="config.session_duration_min" class="mt-2 min-h-[44px] w-full rounded-lg border border-slate-200 px-3 text-sm font-normal"></label>
                <label class="text-xs font-semibold text-slate-600">Charging (menit)<input type="number" min="0" max="1440" x-model.number="config.charging_duration_min" class="mt-2 min-h-[44px] w-full rounded-lg border border-slate-200 px-3 text-sm font-normal"></label>
                <label class="text-xs font-semibold text-slate-600">Jumlah sesi<input type="number" min="1" max="50" x-model.number="config.sessions_count" class="mt-2 min-h-[44px] w-full rounded-lg border border-slate-200 px-3 text-sm font-normal"></label>
                <label class="text-xs font-semibold text-slate-600">Jumlah alat<input type="number" min="1" max="1000" x-model.number="config.tools_count" class="mt-2 min-h-[44px] w-full rounded-lg border border-slate-200 px-3 text-sm font-normal"></label>
                <label class="col-span-2 text-xs font-semibold text-slate-600">HP per alat<input type="number" min="1" max="100" x-model.number="config.hp_per_tool" class="mt-2 min-h-[44px] w-full rounded-lg border border-slate-200 px-3 text-sm font-normal"></label>
                <label class="col-span-2 text-xs font-semibold text-slate-600">Hari libur<select x-model="config.day_off" class="mt-2 min-h-[44px] w-full rounded-lg border border-slate-200 bg-white px-3 text-sm font-normal"><option value="none">Tidak ada hari libur tetap</option><option value="monday">Senin</option><option value="tuesday">Selasa</option><option value="wednesday">Rabu</option><option value="thursday">Kamis</option><option value="friday">Jumat</option><option value="saturday">Sabtu</option><option value="sunday">Minggu</option></select></label>
            </div></div><div class="rounded-2xl bg-slate-900 p-5 text-white"><p class="text-sm font-semibold">Simpan setelah selesai</p><p class="mt-2 text-xs leading-5 text-slate-300">Perubahan di halaman ini adalah rancangan sampai kamu menekan Simpan jadwal. Pengaturan shift tidak mengubah slip gaji yang sudah ada.</p><button type="button" @click="discard()" :disabled="!dirty||saving" class="mt-4 min-h-[44px] w-full rounded-lg border border-slate-600 px-3 text-xs font-semibold disabled:opacity-30">Batalkan perubahan</button></div></aside>
        </section>
        <section x-show="tab==='jadwal'" class="overflow-hidden rounded-2xl border border-slate-200 bg-white"><div class="flex flex-wrap items-center justify-between gap-3 p-6"><div><h2 class="text-lg font-bold text-slate-900">Jadwal harian tim · <span x-text="selectedLabel"></span></h2><p class="mt-1 text-sm text-slate-500">Susunan nama pada tanggal yang dipilih di kalender.</p></div><button type="button" @click="window.print()" class="min-h-[44px] rounded-lg border border-slate-200 px-4 text-sm font-semibold text-slate-600">Cetak jadwal</button></div><div class="overflow-x-auto"><table class="w-full min-w-[620px] border-collapse text-left text-sm"><thead class="bg-slate-50 text-xs text-slate-500"><tr><th class="border-y border-slate-100 p-4 font-semibold">Sesi · WITA</th><template x-for="tool in dayTools" :key="tool"><th class="border-y border-slate-100 p-4 font-semibold" x-text="tool"></th></template></tr></thead><tbody><template x-for="session in daySessions" :key="session.id"><tr><th class="border-b border-slate-100 p-4"><span class="block font-bold text-slate-800" x-text="'Sesi '+session.id"></span><span class="mt-1 block whitespace-nowrap text-xs font-normal text-slate-500" x-text="session.start+'–'+session.end"></span></th><template x-for="tool in dayTools" :key="tool"><td class="border-b border-slate-100 p-4 align-top"><template x-for="(person,index) in dayPeopleAt(session.id,tool)" :key="index"><span class="mb-1 block rounded-lg border border-brand-100 bg-brand-50 px-3 py-2 text-xs font-semibold text-brand-700" x-text="person.name"></span></template><span x-show="dayPeopleAt(session.id,tool).length===0" class="text-xs text-slate-400">Slot kosong</span></td></template></tr></template></tbody></table></div><p class="p-5 text-xs text-slate-500" x-text="'Jeda charging '+dayDraft?.charging_duration_min+' menit di antara sesi. Jam ditampilkan dalam WITA.'"></p></section>
        <section x-show="tab==='bulanan'" class="space-y-5"><div class="rounded-2xl border border-slate-200 bg-white p-6"><div class="flex flex-wrap items-start justify-between gap-4"><div><h2 class="text-lg font-bold text-slate-900">Proyeksi bulanan</h2><p class="mt-1 text-sm text-slate-500">Dihitung dari jadwal setiap tanggal, termasuk perubahan khusus dan hari libur. Tarif simulasi memakai nilai di bawah.</p></div><label class="text-xs font-semibold text-slate-600">Bulan simulasi<input type="month"  :value="month" @change="changeMonth($event.target.value)" class="mt-2 block min-h-[44px] rounded-lg border border-slate-200 px-3 text-sm font-normal"></label></div><div class="mt-6 grid gap-4 sm:grid-cols-2"><label class="text-xs font-semibold text-slate-600">Tarif simulasi per jam video (Rp)<input type="number" min="0" x-model.number="config.hourly_rate" class="mt-2 min-h-[44px] w-full rounded-lg border border-slate-200 px-3 text-sm font-normal"></label><label class="text-xs font-semibold text-slate-600">Estimasi lolos QA (%)<input type="number" min="0" max="100" x-model.number="config.qa_yield_rate" class="mt-2 min-h-[44px] w-full rounded-lg border border-slate-200 px-3 text-sm font-normal"></label></div></div>
            <div class="grid grid-cols-2 gap-3 xl:grid-cols-4"><template x-for="stat in [{label:'Hari kerja',value:activeDays+' hari'},{label:'Produksi video',value:number(monthlyProduction)+' jam'},{label:'Estimasi approved',value:number(monthlyProduction*config.qa_yield_rate/100)+' jam'},{label:'Estimasi biaya penuh',value:money(monthlyCost)}]" :key="stat.label"><div class="rounded-2xl border border-slate-200 bg-white p-5"><p class="text-xs text-slate-500" x-text="stat.label"></p><p class="mt-3 break-words text-lg font-bold text-slate-900" x-text="stat.value"></p></div></template></div>
            <div class="overflow-hidden rounded-2xl border border-slate-200 bg-white"><div class="p-6"><h3 class="font-bold text-slate-900">Rincian per anggota</h3><p class="mt-1 text-xs text-slate-500">Perkiraan kapasitas penuh sebelum hasil QA. Pembayaran aktual mengikuti menit yang disetujui.</p></div><div class="overflow-x-auto"><table class="w-full min-w-[580px] text-left text-sm"><thead class="bg-slate-50 text-xs text-slate-500"><tr><th class="p-4">Nama anggota</th><th class="p-4">Jam kerja</th><th class="p-4">Jam video</th><th class="p-4">Estimasi biaya</th></tr></thead><tbody><template x-for="(person,index) in monthlyRoster" :key="index"><tr class="border-t border-slate-100"><td class="p-4 font-semibold text-slate-800" x-text="person.name"></td><td class="p-4 tabular-nums" x-text="number(person.work)"></td><td class="p-4 tabular-nums" x-text="number(person.production)"></td><td class="p-4 tabular-nums" x-text="money(person.production*config.hourly_rate)"></td></tr></template></tbody></table></div></div>
        </section>
    </div>
</div>
